INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(875915, 99631, 24805, '<td valign="top">well done. the foot in the background feels a little silly and the camera is banking a bit too</td>', 'well done. the foot in the background feels a little silly and the camera is banking a bit too', '2004-08-25 03:00:50.000000', NULL, 1),
(875917, 99074, 25224, '<td valign="top">I like the harry potter font sign.  I don''t feel that it is really provocative.  I would have liked to see the sign, almost burried, as if it were being discovered.  I''ve been to a ton of little stores in California and Oregon that had hidden treasures.  The one common thing, however was that the good things always hid.  They were there, but only if you looked.  That''s what I want to feel in this picture.  It''s there, but I want more.</td>', 'I like the harry potter font sign.  I don''t feel that it is really provocative.  I would have liked to see the sign, almost burried, as if it were being discovered.  I''ve been to a ton of little stores in California and Oregon that had hidden treasures.  The one common thing, however was that the good things always hid.  They were there, but only if you looked.  That''s what I want to feel in this picture.  It''s there, but I want more.', '2004-08-25 03:01:14.000000', NULL, 1),
(875918, 99918, 25203, '<td valign="top">You do realizes that it is impossible to have a game like this... right?</td>', 'You do realizes that it is impossible to have a game like this... right?', '2004-08-25 03:01:19.000000', NULL, 1),
