(876956, 99553, 23614, '<td valign="top">Nice idea, but your background is a bit too distracting.</td>', 'Nice idea, but your background is a bit too distracting.', '2004-08-25 14:33:16.000000', NULL, 1),
(876957, 99509, 5731, '<td valign="top">Beautiful shot, I think would be better without the border.</td>', 'Beautiful shot, I think would be better without the border.', '2004-08-25 14:33:57.000000', NULL, 1),
(876961, 99090, 5731, '<td valign="top">Very interesting shot</td>', 'Very interesting shot', '2004-08-25 14:39:21.000000', NULL, 1),
(876963, 99893, 24169, '<td valign="top">:) Technically good but the only thing I would change would be the position of the lighting - the shadow pn the lip is a little distracting.</td>', ':) Technically good but the only thing I would change would be the position of the lighting - the shadow pn the lip is a little distracting.', '2004-08-25 14:39:39.000000', NULL, 1),
(876964, 99706, 18197, '<td valign="top">Don''t know what this has to do with hope, but I like the picture. Colors, focus and composition are all vry dynamic. Nice job with this one.</td>', 'Don''t know what this has to do with hope, but I like the picture. Colors, focus and composition are all vry dynamic. Nice job with this one.', '2004-08-25 14:40:04.000000', NULL, 1),
(876966, 99918, 21554, '<td valign="top">Lovely image.   Not sure about the ''hope'' aspect here.</td>', 'Lovely image.   Not sure about the ''hope'' aspect here.', '2004-08-25 14:40:10.000000', NULL, 1),
(876967, 98921, 18197, '<td valign="top">I have no idea what this has to do with hope but I like the picture well enough to score it well. I like the sharp contrst between the dark and light areas. I like the focus a DOF.</td>', 'I have no idea what this has to do with hope but I like the picture well enough to score it well. I like the sharp contrst between the dark and light areas. I like the focus a DOF.', '2004-08-25 14:42:06.000000', NULL, 1),
(876971, 99521, 24413, '<td valign="top">I think it would have been better to see the dog''s face a little better.  The colors are nice though.</td>', 'I think it would have been better to see the dog''s face a little better.  The colors are nice though.', '2004-08-25 14:43:52.000000', NULL, 1),
(876972, 99711, 18197, '<td valign="top">This is a vry dramatic shot. Well captures, focused and cropped.  Colors are terrific. I scored it highly even though the tie in to the theme is a bit weak.</td>', 'This is a vry dramatic shot. Well captures, focused and cropped.  Colors are terrific. I scored it highly even though the tie in to the theme is a bit weak.', '2004-08-25 14:44:35.000000', NULL, 1),
(876973, 98670, 24169, '<td valign="top">Nice black and white - quite appropriate for this photo.</td>', 'Nice black and white - quite appropriate for this photo.', '2004-08-25 14:44:54.000000', NULL, 1),
(876976, 99013, 13759, '<td valign="top">There´s no hope at here.</td>', 'There´s no hope at here.', '2004-08-25 14:47:26.000000', NULL, 1),
(876977, 99908, 24413, '<td valign="top">Funny take on the challenge.</td>', 'Funny take on the challenge.', '2004-08-25 14:47:50.000000', NULL, 1),
(876978, 99936, 25553, '<td valign="top">i like the light and the pic, but it could be sharper<br/></td>', 'i like the light and the pic, but it could be sharper', '2004-08-25 14:49:15.000000', NULL, 1),
(876982, 99896, 10634, '<td valign="top">Awesome photo, but not really sure how it fits the challenge. Still, a 6.</td>', 'Awesome photo, but not really sure how it fits the challenge. Still, a 6.', '2004-08-25 14:50:38.000000', NULL, 1),
(876983, 98885, 24413, '<td valign="top">This is a great idea but it seems a bit blurry.</td>', 'This is a great idea but it seems a bit blurry.', '2004-08-25 14:51:09.000000', NULL, 1),
(876984, 99764, 24169, '<td valign="top">Nice colours - I really like the natural look throughout the entire picture. Nice DOF as well.</td>', 'Nice colours - I really like the natural look throughout the entire picture. Nice DOF as well.', '2004-08-25 14:53:00.000000', NULL, 1),
(876986, 99738, 10634, '<td valign="top">Like the idea, but the image is WAY too small. I think the lighting is a little harsh as well, but it is hard to tell with the size of the image. When you resize to fit the constraints of the challenge, the physical size of the image should be as close to the 640 as possible. When you go to save the resized image there should be an options button (at least there is in the 4 different programs I have for photo editing on my computer). In options, adjust the compression factor a little at a time to bring the size of the file to 150 or less. Hope that helps and I look forward to seeing what you produce in the future!</td>', 'Like the idea, but the image is WAY too small. I think the lighting is a little harsh as well, but it is hard to tell with the size of the image. When you resize to fit the constraints of the challenge, the physical size of the image should be as close to the 640 as possible. When you go to save the resized image there should be an options button (at least there is in the 4 different programs I have for photo editing on my computer). In options, adjust the compression factor a little at a time to bring the size of the file to 150 or less. Hope that helps and I look forward to seeing what you produce in the future!', '2004-08-25 14:54:44.000000', NULL, 1),
(876988, 99606, 10634, '<td valign="top">Hate to admit it, but I just don''t get it. It there a shape formed in the smoke that I just can''t pick out? Very nice abstract, though!  5</td>', 'Hate to admit it, but I just don''t get it. It there a shape formed in the smoke that I just can''t pick out? Very nice abstract, though!  5', '2004-08-25 14:57:08.000000', NULL, 1),
(876990, 98905, 24169, '<td valign="top">A little too small to really see the quality of the photograph. Also the pyramid is not quite centered.</td>', 'A little too small to really see the quality of the photograph. Also the pyramid is not quite centered.', '2004-08-25 14:58:02.000000', NULL, 1),
(876995, 99676, 13759, '<td valign="top">Great shot. The only two poles are a bit distractive. But a great shot!</td>', 'Great shot. The only two poles are a bit distractive. But a great shot!', '2004-08-25 15:00:29.000000', NULL, 1),
(876998, 99120, 24169, '<td valign="top">Lovely scenic photo with great colours.</td>', 'Lovely scenic photo with great colours.', '2004-08-25 15:01:36.000000', NULL, 1),
(877005, 99674, 24169, '<td valign="top">Interesting photo but the contrast seems to be a little low as I think there are some details which are too hard to see.</td>', 'Interesting photo but the contrast seems to be a little low as I think there are some details which are too hard to see.', '2004-08-25 15:06:15.000000', NULL, 1),
(877008, 99873, 24413, '<td valign="top">This looks a little slanted to the right.</td>', 'This looks a little slanted to the right.', '2004-08-25 15:08:07.000000', NULL, 1),
(877016, 99705, 25352, '<td valign="top">Excellent! Captures the feeling.</td>', 'Excellent! Captures the feeling.', '2004-08-25 15:10:41.000000', NULL, 1),
(877018, 99376, 13365, '<td valign="top">Beautiful image, however, this would be better if the boat was sitting there not moving. Why would one hope for wind when they have an onboard motor.</td>', 'Beautiful image, however, this would be better if the boat was sitting there not moving. Why would one hope for wind when they have an onboard motor.', '2004-08-25 15:11:32.000000', NULL, 1),
(877019, 99474, 15212, '<td valign="top">The picture itself doesn''t portray hope, but the title makes it work.<br/>Looks hot!</td>', 'The picture itself doesn''t portray hope, but the title makes it work.Looks hot!', '2004-08-25 15:11:34.000000', NULL, 1),
(877022, 99403, 25352, '<td valign="top">Great shot</td>', 'Great shot', '2004-08-25 15:12:24.000000', NULL, 1),
(877025, 99875, 13365, '<td valign="top">Flash reflection is a major distraction, along with lens flare, focus is off. Probably would of been better with a tighter crop. Also kinda a stretch as far as meeting the challenge.</td>', 'Flash reflection is a major distraction, along with lens flare, focus is off. Probably would of been better with a tighter crop. Also kinda a stretch as far as meeting the challenge.', '2004-08-25 15:13:56.000000', NULL, 1),
(877030, 99870, 18197, '<td valign="top">Cleaver idea, and well executed. The colors and textures of the rocks you''ve captured are outstanding. Focus is terrific. Nice highlights and reflections. Borders are risky, but in this case I think you''ve pulled off a good one.  Some will quibble about the central placement of the bottle (comp) but in this case I think it works well to separate the background of the top and bottom halves. Great job!</td>', 'Cleaver idea, and well executed. The colors and textures of the rocks you''ve captured are outstanding. Focus is terrific. Nice highlights and reflections. Borders are risky, but in this case I think you''ve pulled off a good one.  Some will quibble about the central placement of the bottle (comp) but in this case I think it works well to separate the background of the top and bottom halves. Great job!', '2004-08-25 15:15:57.000000', NULL, 1),
(877032, 99614, 13365, '<td valign="top">Would of been much better without the distracting background of the sofa.  Looks like the flash lighting is a bit harsh. Good idea, just needs a better execution next time.</td>', 'Would of been much better without the distracting background of the sofa.  Looks like the flash lighting is a bit harsh. Good idea, just needs a better execution next time.', '2004-08-25 15:17:05.000000', NULL, 1),
(877038, 99783, 18197, '<td valign="top">Wow! This feels like a ribbon winner to me. It is obviously a very dramatic image. The silhouettes work well with the dramatic sky. The pose of your model is unexpected and the lighting (especially of his face against the dark sky) is wonderful. I am one of the school of thought that dislikes borders but I try to remain open minded. In this case, the border detracts IMO. <br/> <br/>In any event, a fine photo. Congratulations.</td>', 'Wow! This feels like a ribbon winner to me. It is obviously a very dramatic image. The silhouettes work well with the dramatic sky. The pose of your model is unexpected and the lighting (especially of his face against the dark sky) is wonderful. I am one of the school of thought that dislikes borders but I try to remain open minded. In this case, the border detracts IMO.  In any event, a fine photo. Congratulations.', '2004-08-25 15:19:50.000000', NULL, 1),
(877040, 99416, 10390, '<td valign="top">Good shot that meets the challenge very well. I like it but it could be better with tighter framing of the girl with the flower. Nice.</td>', 'Good shot that meets the challenge very well. I like it but it could be better with tighter framing of the girl with the flower. Nice.', '2004-08-25 15:20:52.000000', NULL, 1),
(877041, 98795, 18197, '<td valign="top">Very nice image. Good colors and composition. Positive spaces and negative spaces work well. IMO the border detracts. Among my top picks.</td>', 'Very nice image. Good colors and composition. Positive spaces and negative spaces work well. IMO the border detracts. Among my top picks.', '2004-08-25 15:21:22.000000', NULL, 1),
(877042, 99397, 9452, '<td valign="top">IMO, a little burn at the lake would help, but never the less good shot.</td>', 'IMO, a little burn at the lake would help, but never the less good shot.', '2004-08-25 15:22:16.000000', NULL, 1),
(877044, 99830, 24659, '<td valign="top">I like the concept and idea, and the model is showing some real happiness.  I would''ve liked it slightly better if her stance was different. Slightly hunched and closed off, and the wind''s messing the position of the veil.  But good candid.</td>', 'I like the concept and idea, and the model is showing some real happiness.  I would''ve liked it slightly better if her stance was different. Slightly hunched and closed off, and the wind''s messing the position of the veil.  But good candid.', '2004-08-25 15:22:26.000000', NULL, 1),
(877047, 99778, 9452, '<td valign="top">Nice capture and well perfomed.</td>', 'Nice capture and well perfomed.', '2004-08-25 15:23:14.000000', NULL, 1),
(877048, 98726, 18197, '<td valign="top">I have no clue about the tie in to the "hope" theme, but I know I like the picture. Great water texture, colors and focus. Silhouettes work ok. Among my top picks for reasons I can''t completely explain.</td>', 'I have no clue about the tie in to the "hope" theme, but I know I like the picture. Great water texture, colors and focus. Silhouettes work ok. Among my top picks for reasons I can''t completely explain.', '2004-08-25 15:23:19.000000', NULL, 1),
(877049, 99376, 24659, '<td valign="top">The only fluke about your title is that the sails aren''t really up all that much, and it seems to be coasting along just fine.  But a very nice picture.</td>', 'The only fluke about your title is that the sails aren''t really up all that much, and it seems to be coasting along just fine.  But a very nice picture.', '2004-08-25 15:24:01.000000', NULL, 1),
(877055, 99778, 18197, '<td valign="top">Very very nice. I love the contrast between the meadows and the trees. The banding composition (1/3 sky, 1/3 mountains, and 1/3 meadow ... more or less) is effective. The subtle rainbow is a nice touch. I like that the DOF giave some grass in the foreground. Among my top picks.</td>', 'Very very nice. I love the contrast between the meadows and the trees. The banding composition (1/3 sky, 1/3 mountains, and 1/3 meadow ... more or less) is effective. The subtle rainbow is a nice touch. I like that the DOF giave some grass in the foreground. Among my top picks.', '2004-08-25 15:25:46.000000', NULL, 1),
(877059, 99789, 15212, '<td valign="top">Some Post proccesing could really make the rainbow stand out better.</td>', 'Some Post proccesing could really make the rainbow stand out better.', '2004-08-25 15:27:52.000000', NULL, 1),
(877060, 99376, 18197, '<td valign="top">Excellent comp. Colors, focus and DOF work. There''s even a loose tie in to the theme, for a change. Good picture and among my top 10.</td>', 'Excellent comp. Colors, focus and DOF work. There''s even a loose tie in to the theme, for a change. Good picture and among my top 10.', '2004-08-25 15:28:14.000000', NULL, 1),
(877064, 98885, 24970, '<td valign="top">The border works well here.</td>', 'The border works well here.', '2004-08-25 15:29:43.000000', NULL, 1),
(877067, 99432, 24970, '<td valign="top">Though the clutter gives the picture context, it''s also pretty distracting.</td>', 'Though the clutter gives the picture context, it''s also pretty distracting.', '2004-08-25 15:31:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(877072, 98706, 18197, '<td valign="top">Probably a risky title in this forum but I liked the picture well enough to put it in my top 10. Simple, but nicely framed and exposed. High aspect ratio works well full size but makes for a poor thumbnail.</td>', 'Probably a risky title in this forum but I liked the picture well enough to put it in my top 10. Simple, but nicely framed and exposed. High aspect ratio works well full size but makes for a poor thumbnail.', '2004-08-25 15:33:35.000000', NULL, 1),
(877078, 99351, 9452, '<td valign="top">LOL, the expression makes the difference.</td>', 'LOL, the expression makes the difference.', '2004-08-25 15:36:34.000000', NULL, 1),
(877082, 99509, 18197, '<td valign="top">I hope your title is wrong!<br/> <br/>Very strong composition. Contrast and levels are superb. Weak tie in to theme. Among my top picks.</td>', 'I hope your title is wrong! Very strong composition. Contrast and levels are superb. Weak tie in to theme. Among my top picks.', '2004-08-25 15:38:24.000000', NULL, 1),
(877085, 99744, 25553, '<td valign="top">great picture, it almost looks like pull processing. like the unrecognizable background and the breezy feel. beautiful girl as well.</td>', 'great picture, it almost looks like pull processing. like the unrecognizable background and the breezy feel. beautiful girl as well.', '2004-08-25 15:39:08.000000', NULL, 1),
