(877754, 99628, 20809, '<td valign="top">Nude Outtake?</td>', 'Nude Outtake?', '2004-08-25 22:22:02.000000', NULL, 1),
(877759, 99509, 23312, '<td valign="top">That smoke is excellent - in a photographic sense I mean -great detail.  This is a powerful image for me, well done!  My only suggestion - the smokestack seems too short.  I can''t really articulate why I think that, but it just does.</td>', 'That smoke is excellent - in a photographic sense I mean -great detail.  This is a powerful image for me, well done!  My only suggestion - the smokestack seems too short.  I can''t really articulate why I think that, but it just does.', '2004-08-25 22:25:49.000000', NULL, 1),
(877765, 99924, 23312, '<td valign="top">Good "hope" image.  I really like the DOF, it''s just right to convey the message.  I also like the off-white of the lab coat.</td>', 'Good "hope" image.  I really like the DOF, it''s just right to convey the message.  I also like the off-white of the lab coat.', '2004-08-25 22:28:12.000000', NULL, 1),
(877770, 99192, 23312, '<td valign="top">I like this quite a bit - very rich color in the sky.  I''m not so fond of the tree, it detracts from the simple message in the rest of the shot.</td>', 'I like this quite a bit - very rich color in the sky.  I''m not so fond of the tree, it detracts from the simple message in the rest of the shot.', '2004-08-25 22:30:47.000000', NULL, 1),
(877772, 99709, 24951, '<td valign="top">If this photo had zeroed in on fewer or one blader I think it would have been more effective. Add some tension.  I see this just as a sports shot as is.</td>', 'If this photo had zeroed in on fewer or one blader I think it would have been more effective. Add some tension.  I see this just as a sports shot as is.', '2004-08-25 22:31:49.000000', NULL, 1),
(877774, 99432, 24951, '<td valign="top">A bit busy is my opinion.</td>', 'A bit busy is my opinion.', '2004-08-25 22:32:33.000000', NULL, 1),
(877775, 99835, 23312, '<td valign="top">Good shot - this is one of a handful in this challenge that says "hope" without having to read the title.  I''d be tempted to crop it a bit closer on the right.</td>', 'Good shot - this is one of a handful in this challenge that says "hope" without having to read the title.  I''d be tempted to crop it a bit closer on the right.', '2004-08-25 22:32:55.000000', NULL, 1),
(877781, 99867, 24951, '<td valign="top">I think the boy alone would have strengthened the shot</td>', 'I think the boy alone would have strengthened the shot', '2004-08-25 22:35:37.000000', NULL, 1),
