(879582, 99333, 19982, '<td valign="top">Cute picture!  I like the lighting on the halo and wings.  The lighting on child''s face, however, could be improved either with fill flash or a reflector.  Good luck on the challenge.</td>', 'Cute picture!  I like the lighting on the halo and wings.  The lighting on child''s face, however, could be improved either with fill flash or a reflector.  Good luck on the challenge.', '2004-08-27 00:38:23.000000', NULL, 1),
(879583, 99369, 23891, '<td valign="top">Proof that good photoshop skills will put you over the top. The burning and/or saturation at the corners make the shot. Not to mention, great rainbow :-)</td>', 'Proof that good photoshop skills will put you over the top. The burning and/or saturation at the corners make the shot. Not to mention, great rainbow :-)', '2004-08-27 00:40:40.000000', NULL, 1),
