(881750, 98906, 25397, '<td valign="top">excellent idea!</td>', 'excellent idea!', '2004-08-28 19:24:54.000000', NULL, 1),
(881769, 98983, 3087, '<td valign="top">This is a very moving image. I can clearly see the connection the challenge topic. There''s such a sad ambiance to this image because one wonders whether the poor animal''s hopes for a new home are in vain. The eye contact is the most powerful aspect of the image fo me and I like that none of the wire fence interrupts the main part of his face. The way that the low DOF throws out the fence works well adn IO like the way that the inside of his shelter is completely dark. The way the entrance to it curves in a full arc is a nice contrast to the squares of the fence wire. All round strong composition.</td>', 'This is a very moving image. I can clearly see the connection the challenge topic. There''s such a sad ambiance to this image because one wonders whether the poor animal''s hopes for a new home are in vain. The eye contact is the most powerful aspect of the image fo me and I like that none of the wire fence interrupts the main part of his face. The way that the low DOF throws out the fence works well adn IO like the way that the inside of his shelter is completely dark. The way the entrance to it curves in a full arc is a nice contrast to the squares of the fence wire. All round strong composition.', '2004-08-28 19:45:39.000000', NULL, 1),
(881777, 99455, 15242, '<td valign="top">Bonus point for Star Wars reference.  I like the B&amp;W but I might have cropped a little more off the top to get rid or the butt.</td>', 'Bonus point for Star Wars reference.  I like the B&W but I might have cropped a little more off the top to get rid or the butt.', '2004-08-28 19:51:00.000000', NULL, 1),
(881778, 99709, 15242, '<td valign="top">Too small and not very crisp.  Next time use the full size allowed.</td>', 'Too small and not very crisp.  Next time use the full size allowed.', '2004-08-28 19:51:53.000000', NULL, 1),
(881781, 99613, 15242, '<td valign="top">Too bright, no contrast.  The hint of trees in the foreground is distracting, either add more of the trees, or none at all.</td>', 'Too bright, no contrast.  The hint of trees in the foreground is distracting, either add more of the trees, or none at all.', '2004-08-28 19:53:07.000000', NULL, 1),
(881783, 99021, 3306, '<td valign="top">Good idea. Skin is off color.</td>', 'Good idea. Skin is off color.', '2004-08-28 19:54:29.000000', NULL, 1),
(881785, 98905, 15242, '<td valign="top">Over exposed and too bright.  Too small also.  The composition is too plain.  it''s a straight on shot of an object.  It''s a family vacation photo album shot.</td>', 'Over exposed and too bright.  Too small also.  The composition is too plain.  it''s a straight on shot of an object.  It''s a family vacation photo album shot.', '2004-08-28 19:55:17.000000', NULL, 1),
