(881796, 99090, 15242, '<td valign="top">Great photo, but I''m having trouble getting hope out of it.</td>', 'Great photo, but I''m having trouble getting hope out of it.', '2004-08-28 19:59:08.000000', NULL, 1),
(881797, 99937, 15242, '<td valign="top">The photo doesn''t say hope to me, and it''s not very appealing or interesting.</td>', 'The photo doesn''t say hope to me, and it''s not very appealing or interesting.', '2004-08-28 20:00:11.000000', NULL, 1),
(881803, 99893, 15242, '<td valign="top">Did you use the flash as your main lighting source?  It seems over lit and the shadows are distracting.  The frog looks fake also.</td>', 'Did you use the flash as your main lighting source?  It seems over lit and the shadows are distracting.  The frog looks fake also.', '2004-08-28 20:02:57.000000', NULL, 1),
(881804, 99888, 25631, '<td valign="top">you got a nice model for this one ;)</td>', 'you got a nice model for this one ;)', '2004-08-28 20:03:27.000000', NULL, 1),
(881806, 98866, 15242, '<td valign="top">How does two people on a patio having a snack say hope?  I don''t take off points for bad titles, but I don''t say photos meet the challenge because the title.</td>', 'How does two people on a patio having a snack say hope?  I don''t take off points for bad titles, but I don''t say photos meet the challenge because the title.', '2004-08-28 20:04:59.000000', NULL, 1),
