(881923, 99058, 25065, '<td valign="top">Great use of the bride''s train.</td>', 'Great use of the bride''s train.', '2004-08-28 21:55:52.000000', NULL, 1),
(881932, 99773, 25890, '<td valign="top">I believe that this picture is technically decent, although I''m not a big fan of using writing/printed material in visual arts, unless the writing makes a really valuable contribution. What bothers me more is that the message here is somewhat ambiguous. The composition in general -rifle pointing downward, flower covering the barrel- suggests an anti-war statement. Yet, the "red rose" with the "weapon" immediately reminded me of The War of the Roses, The Falange, Red Brigades, Khmer Rouge etc. Not so peaceful! Moreover, as far as I know, the word "truce" does not necessarily mean "peace", it''s more like "to stop fighting for a while (possibly to resume later)". Thus, the picture also has a pro-war feel. Whatever the message is, I wish it were clearer. For instance, for an anti-war statement, any other flower that is not blood-red would have been a better choice in my opinion.</td>', 'I believe that this picture is technically decent, although I''m not a big fan of using writing/printed material in visual arts, unless the writing makes a really valuable contribution. What bothers me more is that the message here is somewhat ambiguous. The composition in general -rifle pointing downward, flower covering the barrel- suggests an anti-war statement. Yet, the "red rose" with the "weapon" immediately reminded me of The War of the Roses, The Falange, Red Brigades, Khmer Rouge etc. Not so peaceful! Moreover, as far as I know, the word "truce" does not necessarily mean "peace", it''s more like "to stop fighting for a while (possibly to resume later)". Thus, the picture also has a pro-war feel. Whatever the message is, I wish it were clearer. For instance, for an anti-war statement, any other flower that is not blood-red would have been a better choice in my opinion.', '2004-08-28 22:05:07.000000', NULL, 1),
(881933, 99482, 24659, '<td valign="top">I like the photo, though the horizon could be a little more level.</td>', 'I like the photo, though the horizon could be a little more level.', '2004-08-28 22:05:30.000000', NULL, 1),
(881936, 99485, 24659, '<td valign="top">Good photo, I don''t really think of hope though at this point.  Maybe not to be struck by one.</td>', 'Good photo, I don''t really think of hope though at this point.  Maybe not to be struck by one.', '2004-08-28 22:09:14.000000', NULL, 1),
(881944, 99781, 25890, '<td valign="top">But for the title I couldn''t have figured out that this was a lighthouse, and would have had a hard time seeing how a nice picture of a nondescript tower represented hope. Maybe a less steep angle, less light/glare on the left side of the tower and a light beam from the top of the tower cutting through the air, and this picture would have been stunning.</td>', 'But for the title I couldn''t have figured out that this was a lighthouse, and would have had a hard time seeing how a nice picture of a nondescript tower represented hope. Maybe a less steep angle, less light/glare on the left side of the tower and a light beam from the top of the tower cutting through the air, and this picture would have been stunning.', '2004-08-28 22:18:19.000000', NULL, 1),
