(882670, 99423, 24939, '<td valign="top">Seems very red and blurry to me.</td>', 'Seems very red and blurry to me.', '2004-08-29 16:08:32.000000', NULL, 1),
(882671, 99926, 24939, '<td valign="top">Wonderful lighting and composition.</td>', 'Wonderful lighting and composition.', '2004-08-29 16:08:50.000000', NULL, 1),
