INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(882907, 99935, 17126, '<td valign="top">I liked the picture until i saw "hope" written in the sand. i''d rather see a cool picture that''s off topic than to see a good picture made completely lame with an attempt to make a connection that really doesn''t exist. This is the most blatant this round.<br/> <br/>Having said that, photoshop that word out, and adjust the contrast and saturation a bit. I love the picture, despite the stupid word written in the sand.</td>', 'I liked the picture until i saw "hope" written in the sand. i''d rather see a cool picture that''s off topic than to see a good picture made completely lame with an attempt to make a connection that really doesn''t exist. This is the most blatant this round. Having said that, photoshop that word out, and adjust the contrast and saturation a bit. I love the picture, despite the stupid word written in the sand.', '2004-08-29 22:20:16.000000', NULL, 1),
