(884690, 99891, 19248, '<td valign="top">Stunning captire. hit the challenge on the head. 10</td>', 'Stunning captire. hit the challenge on the head. 10', '2004-08-30 22:49:14.000000', NULL, 1),
(884691, 98885, 23680, '<td valign="top">Too blurry</td>', 'Too blurry', '2004-08-30 22:49:25.000000', NULL, 1),
