(884697, 99691, 23680, '<td valign="top">I don''t get it?</td>', 'I don''t get it?', '2004-08-30 22:50:51.000000', NULL, 1),
(884700, 99631, 19248, '<td valign="top">Hits the summer day''s hope on the head.  The coloring seems overdone.  9</td>', 'Hits the summer day''s hope on the head.  The coloring seems overdone.  9', '2004-08-30 22:51:55.000000', NULL, 1),
(884704, 98591, 19248, '<td valign="top">Tremendous picture.  Her eyes really show concern.  9</td>', 'Tremendous picture.  Her eyes really show concern.  9', '2004-08-30 22:52:49.000000', NULL, 1),
(884708, 99800, 19248, '<td valign="top">WOW.  The bird is an added bonus.  10</td>', 'WOW.  The bird is an added bonus.  10', '2004-08-30 22:53:38.000000', NULL, 1),
(884709, 99607, 23680, '<td valign="top">I like the concept, just would have liked it better if it was a little sharper</td>', 'I like the concept, just would have liked it better if it was a little sharper', '2004-08-30 22:53:40.000000', NULL, 1),
(884714, 99734, 23680, '<td valign="top">too small to reallyl get a good look at, but looks like a good concept</td>', 'too small to reallyl get a good look at, but looks like a good concept', '2004-08-30 22:55:54.000000', NULL, 1),
(884727, 99483, 24970, '<td valign="top">I love all the birds, especially the one still in flight. They give this picture so much extra character. I might have put a little more space on the right of the photo; other than that, nice job!</td>', 'I love all the birds, especially the one still in flight. They give this picture so much extra character. I might have put a little more space on the right of the photo; other than that, nice job!', '2004-08-30 23:03:10.000000', NULL, 1),
(884728, 99757, 23680, '<td valign="top">great action shot</td>', 'great action shot', '2004-08-30 23:04:04.000000', NULL, 1),
(884756, 99089, 10263, '<td valign="top">Very moving. Makes me want to know more</td>', 'Very moving. Makes me want to know more', '2004-08-30 23:27:25.000000', NULL, 1);
