(884992, 99610, 16241, '<td valign="top">studing &amp; working..!</td>', 'studing & working..!', '2004-08-31 02:54:07.000000', NULL, 1),
(885002, 98908, 16241, '<td valign="top">i like it</td>', 'i like it', '2004-08-31 03:07:03.000000', NULL, 1),
(885003, 99791, 16241, '<td valign="top">very nice</td>', 'very nice', '2004-08-31 03:07:43.000000', NULL, 1),
(885014, 98878, 164, '<td valign="top">Good colors and contrast with the darkness.</td>', 'Good colors and contrast with the darkness.', '2004-08-31 03:26:27.000000', NULL, 1),
(885015, 98599, 164, '<td valign="top">I like the size of this backside. good picture but I don''t like the backdrop</td>', 'I like the size of this backside. good picture but I don''t like the backdrop', '2004-08-31 03:28:07.000000', NULL, 1),
(885021, 99370, 24805, '<td valign="top">i''m not sure about this, i don''t like it, but i''m not sure it isn''t good. strange anyway. keep experimenting!</td>', 'i''m not sure about this, i don''t like it, but i''m not sure it isn''t good. strange anyway. keep experimenting!', '2004-08-31 03:40:14.000000', NULL, 1),
(885022, 99376, 24805, '<td valign="top">looks ok without it anyway ;~)</td>', 'looks ok without it anyway ;~)', '2004-08-31 03:41:01.000000', NULL, 1),
(885024, 99706, 24805, '<td valign="top">this isn''t a bad picture, but it really could be more on-topic. it aslo looks very "smart-blurred." that''s a filter to use in extreme moderation most of the time.</td>', 'this isn''t a bad picture, but it really could be more on-topic. it aslo looks very "smart-blurred." that''s a filter to use in extreme moderation most of the time.', '2004-08-31 03:42:10.000000', NULL, 1),
(885026, 99455, 24805, '<td valign="top">like the grin. the composition needs work pretty badly. perhaps if you had blurred the background? BW was a good choice!</td>', 'like the grin. the composition needs work pretty badly. perhaps if you had blurred the background? BW was a good choice!', '2004-08-31 03:43:02.000000', NULL, 1),
(885034, 99823, 25652, '<td valign="top">I like this on the tile floor. Good composition.</td>', 'I like this on the tile floor. Good composition.', '2004-08-31 04:24:47.000000', NULL, 1),
(885044, 99783, 2978, '<td valign="top">This is the great combination of interpretation and execution. The texture of the ground and the sky creates such a mood to the photo. On top of that, the tree and the model are well composed to deliver the theme. Well done!</td>', 'This is the great combination of interpretation and execution. The texture of the ground and the sky creates such a mood to the photo. On top of that, the tree and the model are well composed to deliver the theme. Well done!', '2004-08-31 05:17:29.000000', NULL, 1),
(885046, 99090, 2978, '<td valign="top">Speechless except I love it!</td>', 'Speechless except I love it!', '2004-08-31 05:21:03.000000', NULL, 1),
(885058, 98863, 24659, '<td valign="top">The timeliness of the photo is dated - a photo of a woman who probably is not pregnant anymore, a testing stick, and a children''s sock that is obviously worn...</td>', 'The timeliness of the photo is dated - a photo of a woman who probably is not pregnant anymore, a testing stick, and a children''s sock that is obviously worn...', '2004-08-31 06:35:39.000000', NULL, 1),
(885071, 99089, 24888, '<td valign="top">Hoping that soon her plight will end.</td>', 'Hoping that soon her plight will end.', '2004-08-31 07:13:44.000000', NULL, 1),
(885078, 99272, 19294, '<td valign="top">Please, read Exodus 20:4,5</td>', 'Please, read Exodus 20:4,5', '2004-08-31 07:17:47.000000', NULL, 1),
(885080, 99821, 19294, '<td valign="top">Bad, bad, really bad</td>', 'Bad, bad, really bad', '2004-08-31 07:20:46.000000', NULL, 1),
(885082, 98599, 19294, '<td valign="top">I think that your backside is really nice  ;-)</td>', 'I think that your backside is really nice  ;-)', '2004-08-31 07:23:39.000000', NULL, 1),
(885084, 99614, 19294, '<td valign="top">Rubish. We don´t need that thing to talk with God. Rubish.</td>', 'Rubish. We don´t need that thing to talk with God. Rubish.', '2004-08-31 07:25:24.000000', NULL, 1),
(885090, 99179, 19294, '<td valign="top">Hay que tener esperanza, hermana hispana,  pero la Biblia condena el uso de imágenes como esa cruz.  No hace falta usarla para acercarnos a Dios.  Lee Exodo 20:4,5</td>', 'Hay que tener esperanza, hermana hispana,  pero la Biblia condena el uso de imágenes como esa cruz.  No hace falta usarla para acercarnos a Dios.  Lee Exodo 20:4,5', '2004-08-31 07:30:22.000000', NULL, 1),
(885096, 99922, 19294, '<td valign="top">Fahrenheit 9/11</td>', 'Fahrenheit 9/11', '2004-08-31 07:32:24.000000', NULL, 1),
(885102, 99690, 19294, '<td valign="top">Not nice.</td>', 'Not nice.', '2004-08-31 07:37:12.000000', NULL, 1),
(885152, 99823, 21551, '<td valign="top">Amen</td>', 'Amen', '2004-08-31 08:45:47.000000', NULL, 1),
(885200, 99342, 23245, '<td valign="top">Nice find</td>', 'Nice find', '2004-08-31 10:09:19.000000', NULL, 1),
(885277, 98980, 25483, '<td valign="top">I love how you captured the color of the ocean, nice blue to white tween.  Would like to see more detail in cliffs but i gather you were already using a fairly slow shutter speed to begin with.  Composition very good, all in all a 7</td>', 'I love how you captured the color of the ocean, nice blue to white tween.  Would like to see more detail in cliffs but i gather you were already using a fairly slow shutter speed to begin with.  Composition very good, all in all a 7', '2004-08-31 11:25:25.000000', NULL, 1),
(885290, 99495, 25483, '<td valign="top">I guess your one of those ladies who doesnt have much use for their 3.5'' floppy drive :)    I like your shot, a bit blurry to the lower right but generaly a good idea.  7</td>', 'I guess your one of those ladies who doesnt have much use for their 3.5'' floppy drive :)    I like your shot, a bit blurry to the lower right but generaly a good idea.  7', '2004-08-31 11:30:23.000000', NULL, 1),
(885382, 99278, 1570, '<td valign="top">oh, wow, red eye! if you really love this picture and wanted to submit it anyway, you could''ve converted it to b/w or sepia to get rid of it... as it is, it''s very very prominent!</td>', 'oh, wow, red eye! if you really love this picture and wanted to submit it anyway, you could''ve converted it to b/w or sepia to get rid of it... as it is, it''s very very prominent!', '2004-08-31 12:55:19.000000', NULL, 1),
(885384, 99868, 19608, '<td valign="top">It''s a nice macro - good exposure, focus and composition/  But - it''s not something I would see hanging on an office wall.  Extra point for originality and out-of-the-box idea.</td>', 'It''s a nice macro - good exposure, focus and composition/  But - it''s not something I would see hanging on an office wall.  Extra point for originality and out-of-the-box idea.', '2004-08-31 12:56:19.000000', NULL, 1),
(885404, 98996, 19608, '<td valign="top">You have a very interesting and colorful flower - shot from an unusual angle.  Compositionally - the grassy area at bottom left is very disorganized/busy.  Excellent exposure.  Slight lens flare is just a tad distracting.  It is a bit difficult to connect hope to this image.</td>', 'You have a very interesting and colorful flower - shot from an unusual angle.  Compositionally - the grassy area at bottom left is very disorganized/busy.  Excellent exposure.  Slight lens flare is just a tad distracting.  It is a bit difficult to connect hope to this image.', '2004-08-31 13:17:41.000000', NULL, 1),
(885407, 98983, 19608, '<td valign="top">Emotional and well done B&amp;W.    Composition and exposure spot on.  Dogs have hope?</td>', 'Emotional and well done B&W.    Composition and exposure spot on.  Dogs have hope?', '2004-08-31 13:19:17.000000', NULL, 1),
(885413, 99738, 19608, '<td valign="top">You image is strong - a good rendition of hope.  It is just too small to really vote accurately.  You need to use more of the allowed 640 pixel /side and 150k file size.</td>', 'You image is strong - a good rendition of hope.  It is just too small to really vote accurately.  You need to use more of the allowed 640 pixel /side and 150k file size.', '2004-08-31 13:27:50.000000', NULL, 1),
(885414, 99628, 19608, '<td valign="top">It''s an interesting concept, well designed and exposed.  Not sure it yells "hope" except for the title.</td>', 'It''s an interesting concept, well designed and exposed.  Not sure it yells "hope" except for the title.', '2004-08-31 13:29:29.000000', NULL, 1),
(885418, 99521, 19608, '<td valign="top">A dog silhouette against a very blurry background.  It has lots of graphic appeal in a colorful way.  The blue and yellow work well together and the dog''s shape become very ominous.  Hope?  Don''t see it.</td>', 'A dog silhouette against a very blurry background.  It has lots of graphic appeal in a colorful way.  The blue and yellow work well together and the dog''s shape become very ominous.  Hope?  Don''t see it.', '2004-08-31 13:32:20.000000', NULL, 1),
(885420, 99238, 19608, '<td valign="top">It''s nice colors.  Looks like getting any waves that day was really a false hope.  No real subject here.</td>', 'It''s nice colors.  Looks like getting any waves that day was really a false hope.  No real subject here.', '2004-08-31 13:33:39.000000', NULL, 1),
(885423, 99800, 19608, '<td valign="top">Classic example of hope.  The bird''s flying through was very fortunate - or well planned.  Sun a bit hot - but it works fine for the way you''ve presented this.  The rays are perfect.</td>', 'Classic example of hope.  The bird''s flying through was very fortunate - or well planned.  Sun a bit hot - but it works fine for the way you''ve presented this.  The rays are perfect.', '2004-08-31 13:35:31.000000', NULL, 1),
(885429, 99875, 25468, '<td valign="top">I don''t like the cropping. You should have cropped around the girls so you would not see the giant spot light in the background.</td>', 'I don''t like the cropping. You should have cropped around the girls so you would not see the giant spot light in the background.', '2004-08-31 13:38:56.000000', NULL, 1),
(885430, 99474, 1368, '<td valign="top">beautiful would like to see a person instead of the dog though :) 9</td>', 'beautiful would like to see a person instead of the dog though :) 9', '2004-08-31 13:39:34.000000', NULL, 1),
(885432, 99416, 19608, '<td valign="top">Woo hoo.  This is my 2500th comment.  I guess you win some sort of lottery or something.  The image is well shot.  I like the way you''ve placed the flowers - except for the one behind her left arm.  The model''s look is perfect and I love the wind-blown look to her hair.  A small point - the necklace and the earring seem to be connected - a bit awkward. Too bad the sky was not more blue up near her head.  The white clouds hurt it a bit.  But - it certainly meets the challenge - and is an excellent submission too.  Thanks for sharing.</td>', 'Woo hoo.  This is my 2500th comment.  I guess you win some sort of lottery or something.  The image is well shot.  I like the way you''ve placed the flowers - except for the one behind her left arm.  The model''s look is perfect and I love the wind-blown look to her hair.  A small point - the necklace and the earring seem to be connected - a bit awkward. Too bad the sky was not more blue up near her head.  The white clouds hurt it a bit.  But - it certainly meets the challenge - and is an excellent submission too.  Thanks for sharing.', '2004-08-31 13:40:15.000000', NULL, 1),
(885435, 98917, 19608, '<td valign="top">Nice lighting, composition, and exposure.  The dark blue color reall works well with the plant''s colors.</td>', 'Nice lighting, composition, and exposure.  The dark blue color reall works well with the plant''s colors.', '2004-08-31 13:45:43.000000', NULL, 1),
(885436, 99416, 1368, '<td valign="top">Beautiful portrait :)</td>', 'Beautiful portrait :)', '2004-08-31 13:46:07.000000', NULL, 1),
(885438, 99830, 19608, '<td valign="top">One happy bride!  Nice entry for hope for sure.  Good exposure in nice lighting.</td>', 'One happy bride!  Nice entry for hope for sure.  Good exposure in nice lighting.', '2004-08-31 13:47:01.000000', NULL, 1),
(885445, 99507, 19608, '<td valign="top">Nice capture - great positioning of the silhouette and ball.  Too bad the wires were not an actual net - it''s a bit awkward.  Colors are subtle but very nice.</td>', 'Nice capture - great positioning of the silhouette and ball.  Too bad the wires were not an actual net - it''s a bit awkward.  Colors are subtle but very nice.', '2004-08-31 13:54:40.000000', NULL, 1),
(885470, 99714, 23338, '<td valign="top">Without the title, I''d never have gotten "Hope" out of this.  Interesting concept though.</td>', 'Without the title, I''d never have gotten "Hope" out of this.  Interesting concept though.', '2004-08-31 14:11:44.000000', NULL, 1),
(885472, 99922, 19608, '<td valign="top">Very interesting subtle lighting makes this very unique.</td>', 'Very interesting subtle lighting makes this very unique.', '2004-08-31 14:12:05.000000', NULL, 1),
(885476, 99923, 19608, '<td valign="top">Exceptional job of "printing."  Strong whites and black blacks are just perfect.  The heavy black border doesn''t work for me - but no points deducted for it.  Overall a great rendition of hope - thanks for sharing.</td>', 'Exceptional job of "printing."  Strong whites and black blacks are just perfect.  The heavy black border doesn''t work for me - but no points deducted for it.  Overall a great rendition of hope - thanks for sharing.', '2004-08-31 14:14:13.000000', NULL, 1),
(885478, 98713, 23338, '<td valign="top">Cute photograph of a pet.   I have trouble translating it to "hope" though, even with the title.    Really, no hoping about it - the dog already HAS the bone.</td>', 'Cute photograph of a pet.   I have trouble translating it to "hope" though, even with the title.    Really, no hoping about it - the dog already HAS the bone.', '2004-08-31 14:15:12.000000', NULL, 1),
(885482, 99868, 23338, '<td valign="top">Ok, so if I KNEW in advance what the little pill was, then maybe I would have translated this into "hope" - at least after 8 to 10 tries.  I would have started with: Viagra?  Fun time tonight?  You up for it?  Doing anything?</td>', 'Ok, so if I KNEW in advance what the little pill was, then maybe I would have translated this into "hope" - at least after 8 to 10 tries.  I would have started with: Viagra?  Fun time tonight?  You up for it?  Doing anything?', '2004-08-31 14:17:58.000000', NULL, 1),
(885483, 99790, 19608, '<td valign="top">Nice composition and lighting.  Exposure is perfect.  The fact that the candles are un-used adds a bit of mystery for me.</td>', 'Nice composition and lighting.  Exposure is perfect.  The fact that the candles are un-used adds a bit of mystery for me.', '2004-08-31 14:18:34.000000', NULL, 1),
(885485, 99472, 19608, '<td valign="top">Nice idea - composition and exposure.  It really works well in black and white.</td>', 'Nice idea - composition and exposure.  It really works well in black and white.', '2004-08-31 14:20:08.000000', NULL, 1),
(885492, 99432, 19608, '<td valign="top">It''s an interesting image albeit a bit cluttered.  Hope?  Fish?</td>', 'It''s an interesting image albeit a bit cluttered.  Hope?  Fish?', '2004-08-31 14:22:25.000000', NULL, 1),
(885495, 99928, 19608, '<td valign="top">You have some nice colors that work well together, but the composition and focus take away from the image.  It''s really hard to see what you are trying to tell me.</td>', 'You have some nice colors that work well together, but the composition and focus take away from the image.  It''s really hard to see what you are trying to tell me.', '2004-08-31 14:24:40.000000', NULL, 1),
(885497, 99765, 23338, '<td valign="top">Boy, am I dumb.  I''m going past this image now for about the sixth or seventh time at a minimum when I just finally noticed the writing on the discarded packs, "Hope, lights".  Now the title makes sense.   Ok, I''ll raise it from a 3 to a 5.   My problem with this whole challenge has been finding that elusive, positive feeling of "Hope" in the images.  At least, I''ve been interpreting "Hope" as being on the positive side of the scale.  I know you can have negative hope, and cigarettes connotate a negative for me.   Pretty nice focus and color though.  And a cute idea.</td>', 'Boy, am I dumb.  I''m going past this image now for about the sixth or seventh time at a minimum when I just finally noticed the writing on the discarded packs, "Hope, lights".  Now the title makes sense.   Ok, I''ll raise it from a 3 to a 5.   My problem with this whole challenge has been finding that elusive, positive feeling of "Hope" in the images.  At least, I''ve been interpreting "Hope" as being on the positive side of the scale.  I know you can have negative hope, and cigarettes connotate a negative for me.   Pretty nice focus and color though.  And a cute idea.', '2004-08-31 14:26:37.000000', NULL, 1),
(885499, 98670, 19608, '<td valign="top">The title says "freedom" - the flip-flops say "freedom" - but the model''s pose says "rejected" or "sad" or "unhappy."  Nice exposure and composition.  The bald sky detracts a bit.</td>', 'The title says "freedom" - the flip-flops say "freedom" - but the model''s pose says "rejected" or "sad" or "unhappy."  Nice exposure and composition.  The bald sky detracts a bit.', '2004-08-31 14:27:02.000000', NULL, 1),
(885505, 99139, 19608, '<td valign="top">Great expression - but would be better yet with more light on the face.  The parrot seems fairly comfortable in that unusual position - wouldn''t think he''d like that.  Nice idea - a bit of a stretch for hope.</td>', 'Great expression - but would be better yet with more light on the face.  The parrot seems fairly comfortable in that unusual position - wouldn''t think he''d like that.  Nice idea - a bit of a stretch for hope.', '2004-08-31 14:29:10.000000', NULL, 1),
(885508, 99704, 23338, '<td valign="top">I don''t get it.  Even with the title.  I know there is something in there you are trying to tell me; it just isn''t coming through.  Life (Ok, there are plants and trees), death (I don''t see that here), and hope for the living (Where do you derive that from this image?).  Maybe there is something about that odd shape in the water (like a piece of discarded metal) that I''m not seeing.   What is it?</td>', 'I don''t get it.  Even with the title.  I know there is something in there you are trying to tell me; it just isn''t coming through.  Life (Ok, there are plants and trees), death (I don''t see that here), and hope for the living (Where do you derive that from this image?).  Maybe there is something about that odd shape in the water (like a piece of discarded metal) that I''m not seeing.   What is it?', '2004-08-31 14:30:47.000000', NULL, 1),
(885509, 98528, 19608, '<td valign="top">Nice rendition indeed.  Brilliant whites and deep blacks with a superb range in between.  The use of the bird house and its position is great.  Crop some from the left to make it even stronger.</td>', 'Nice rendition indeed.  Brilliant whites and deep blacks with a superb range in between.  The use of the bird house and its position is great.  Crop some from the left to make it even stronger.', '2004-08-31 14:31:06.000000', NULL, 1),
(885511, 99683, 19608, '<td valign="top">Cute idea - and it works very well in the sepia-like colors.  I''d crop the tree in the left top corner totally out.</td>', 'Cute idea - and it works very well in the sepia-like colors.  I''d crop the tree in the left top corner totally out.', '2004-08-31 14:32:38.000000', NULL, 1),
(885513, 99803, 23338, '<td valign="top">Without the title, I don''t get "Hope" out of this.  At least not in the first ten words that flash through my mind: "Stars", "Stripes", "Red", "White", "Blue", "USA", "Freedom", "Pride", "Honor", "Francis Scott Key", "Ameica the Beautiful" ... see?</td>', 'Without the title, I don''t get "Hope" out of this.  At least not in the first ten words that flash through my mind: "Stars", "Stripes", "Red", "White", "Blue", "USA", "Freedom", "Pride", "Honor", "Francis Scott Key", "Ameica the Beautiful" ... see?', '2004-08-31 14:34:32.000000', NULL, 1),
(885515, 99824, 19608, '<td valign="top">A decent insect picture.  Good flat lighting makes a nice exposure.  Hope is really hard to find here.</td>', 'A decent insect picture.  Good flat lighting makes a nice exposure.  Hope is really hard to find here.', '2004-08-31 14:35:14.000000', NULL, 1),
(885519, 99107, 23338, '<td valign="top">Take away the title and what do you get?  Lots of things, but "Hope" doesn''t seem like one of them - especially to this non-archer.  Like: "Wow, look at that bow; complicated, isn''t it!", or, "Wonder if he''s shooting at live targets or circles on a bale of hay", or "Nice angle for a photograph", or "Look at the how the shadows play off the shirt".    None of them involved "Hope".</td>', 'Take away the title and what do you get?  Lots of things, but "Hope" doesn''t seem like one of them - especially to this non-archer.  Like: "Wow, look at that bow; complicated, isn''t it!", or, "Wonder if he''s shooting at live targets or circles on a bale of hay", or "Nice angle for a photograph", or "Look at the how the shadows play off the shirt".    None of them involved "Hope".', '2004-08-31 14:38:00.000000', NULL, 1),
(885526, 99722, 23338, '<td valign="top">Yeh, I''ve tried this at the Rennaisance Festival, too.   And, I had "hope" that I could get further up the rope ladder than the previous person.  But, as a representative image for the positive feeling "Hope", how many people would look at this photo and think of the word, "Hope"?   IMHO, not too many.  Most would look at it as a snapshot of a fun moment.  Or a pretty woman.   As a piece of photographic "art", I would have wished for a less distracting background, or that angle of the photograph were such that the woman in the background was a dual subject in the image and more in focus - the subject on the rope and the entertained and amused figure watching.   Anyway, those are just my opinions.  And, it IS fun to try.</td>', 'Yeh, I''ve tried this at the Rennaisance Festival, too.   And, I had "hope" that I could get further up the rope ladder than the previous person.  But, as a representative image for the positive feeling "Hope", how many people would look at this photo and think of the word, "Hope"?   IMHO, not too many.  Most would look at it as a snapshot of a fun moment.  Or a pretty woman.   As a piece of photographic "art", I would have wished for a less distracting background, or that angle of the photograph were such that the woman in the background was a dual subject in the image and more in focus - the subject on the rope and the entertained and amused figure watching.   Anyway, those are just my opinions.  And, it IS fun to try.', '2004-08-31 14:44:28.000000', NULL, 1),
(885529, 99368, 23338, '<td valign="top">Lots of stuff to look at in this cute pet photo.  I just don''t see it as an artistic representation of the positive feeling, "Hope".     Sorry.   That''s just my feeling.  Cute title and bird though.</td>', 'Lots of stuff to look at in this cute pet photo.  I just don''t see it as an artistic representation of the positive feeling, "Hope".     Sorry.   That''s just my feeling.  Cute title and bird though.', '2004-08-31 14:46:51.000000', NULL, 1),
(885537, 99060, 23338, '<td valign="top">Yeh, there''s just something about it - great contrast with lots of white space, just the hint of the barrier holding him back, the instinctive drive for preservation fueling a constant search for escape, nice colors and selective focus on the slower areas of movement, good cropping and composition.  He''s also got a pretty jaunty stance.   I just loved it.</td>', 'Yeh, there''s just something about it - great contrast with lots of white space, just the hint of the barrier holding him back, the instinctive drive for preservation fueling a constant search for escape, nice colors and selective focus on the slower areas of movement, good cropping and composition.  He''s also got a pretty jaunty stance.   I just loved it.', '2004-08-31 14:53:08.000000', NULL, 1),
(885539, 99935, 23338, '<td valign="top">Love the image; question the symbolism.  Hope so transitory; colors so dark and foreboding.   Central blotch in clouds looks out of place.  Couldn''t get the photo out of my mind.  Kept coming back to it.  Really nice effort and composition.</td>', 'Love the image; question the symbolism.  Hope so transitory; colors so dark and foreboding.   Central blotch in clouds looks out of place.  Couldn''t get the photo out of my mind.  Kept coming back to it.  Really nice effort and composition.', '2004-08-31 14:55:54.000000', NULL, 1),
