(898345, 98616, 16499, '<td valign="top"><br/>Very good. My mark is 8. Insufficient softness: it should ehance the shadow cut on the face. Try several layers of transparent plasic - ice effect!<br/><br/><i>Message edited by HBunch - Critique Club status removed.</i></td>', 'Very good. My mark is 8. Insufficient softness: it should ehance the shadow cut on the face. Try several layers of transparent plasic - ice effect!Message edited by HBunch - Critique Club status removed.', '2004-09-07 23:58:47.000000', NULL, 0),
(898352, 99578, 16499, '<td valign="top"><br/>Not in focus. My mark for this: 6.<br/><br/><i>Message edited by HBunch - Critique Club status removed.</i></td>', 'Not in focus. My mark for this: 6.Message edited by HBunch - Critique Club status removed.', '2004-09-08 00:00:53.000000', NULL, 0),
(898358, 99482, 16499, '<td valign="top"><br/>Horizon... Color casting... Shadow at the bottom... Central comosition does not play here at all.<br/><br/><i>Message edited by HBunch - Critique Club status removed.</i></td>', 'Horizon... Color casting... Shadow at the bottom... Central comosition does not play here at all.Message edited by HBunch - Critique Club status removed.', '2004-09-08 00:03:54.000000', NULL, 0),
